text:
toolbarbutton[is="toolbarbutton-menu-button"] {
  align-items: stretch;
  flex-direction: row;
}

.toolbarbutton-menubutton-button {
  align-items: center;
  justify-content: center;
  flex-direction: column;
  min-block-size: 24px;
  min-inline-size: 32px;
  margin: 4px 1px;
  padding: 1px 5px;

  & > .toolbarbutton-icon {
    padding: 1px;
  }
}

.toolbarbutton-1:not(.qfb-tag-button),
.toolbarbutton-menubutton-button {
  color: inherit;
}
